<script setup>
import {computed} from 'vue';import {stateSpans,sources,clock,duration,INCIDENT} from './data';import {useTimeline} from './useTimeline';import TimeAxis from './TimeAxis.vue';
const {state,inspect,setWindow}=useTimeline();
const rows=computed(()=>sources.filter(s=>!state.source||state.source===s.id).map(s=>({...s,spans:stateSpans.filter(x=>x.source===s.id&&x.start<state.end&&x.end>state.start)})));
const pos=t=>Math.max(0,Math.min(100,(t-state.start)/(state.end-state.start)*100));
function open(x){inspect(Math.max(state.start,x.start),Math.min(state.end,x.end),{source:x.source,...(x.kind==='derived'?{target:'T-041',note:'פער מחושב: 102 שניות בין קליטת הקוד לפעולה המתועדת הראשונה למטרה T-041. פעילות במטרות אחרות אינה נספרת כאן.',refs:['EV-106','EV-111']}:{}),...(x.kind==='unknown'?{note:'קובץ הסנסור חסר באינטרוול הזה בסימולציה. לא ניתן להסיק מכאן שהסנסור לא פעל.',refs:[]}:{}),...(x.kind==='critical'?{note:x.label,refs:[x.evidence]}:{})});}
</script><template><div class="inline-note"><span>שכבת מצבים מדומה, נפרדת מסינון רשומות. רציפות כאן מבוססת על נתוני הסימולטור.</span><button @click="setWindow(INCIDENT-30,INCIDENT+210)">בחינת 102 השניות ↗</button></div><div class="ribbons"><div class="lane-axis"><TimeAxis :start="state.start" :end="state.end"/><span>מערכת מקור</span></div><div class="ribbon-row" v-for="s in rows" :key="s.id"><div class="ribbon-track" dir="ltr"><button v-for="x in s.spans" :key="x.start" class="state-span" :class="x.kind" :style="{left:pos(x.start)+'%',width:Math.max(.55,pos(x.end)-pos(x.start))+'%'}" :title="x.label+' · '+clock(x.start)+' — '+clock(x.end)+' · '+duration(x.end-x.start)" @click="open(x)"><span>{{x.label}}</span></button><span v-if="!s.spans.length" class="no-state">אין מצב מוגדר בחלון הזה</span></div><strong class="matrix-label">{{s.label}}</strong></div></div><div class="state-legend"><span class="normal">━ מצב מדווח</span><span class="critical">━ תקלה</span><span class="unknown">▨ חסר מקור / לא ידוע</span><span class="derived">┄ ללא פעולה מתועדת</span><span class="soft">┄ קול · זמן מיוחס</span></div><p class="plot-note">״ללא פעולה״ הוא פער מחושב בין EV-106 ל־EV-111 עבור T-041 בלבד. היעדר רשומה אינו מוכיח מה המפעיל ראה.</p></template>